  function platformTenants(){return `${pageHead('Организации','Tenants платформы, тарифы, лимиты, состояние и активность.',btn('Создать организацию','plus','primary'))}<div class="grid cols-4">${metric('Tenants','18','15 активных','building')}${metric('Охранников MAU','1 284','+8.2%','users')}${metric('Активных смен','163','сейчас','clock')}${metric('Интеграции','99.96%','за 24 часа','activity')}</div>${searchToolbar('Название, ИНН, slug...')}<div class="table-wrap"><table class="data-table"><thead><tr><th>Организация</th><th>Тариф</th><th>Сотрудники</th><th>Объекты</th><th>Health</th></tr></thead><tbody>${row('ООО ЧОП «Оберег»','obereg',['Pilot','247','9',pill('HEALTHY','success')],'platform:tenant')}${row('ООО ЧОП «Барьер»','barrier',['Pilot','121','6',pill('HEALTHY','success')],'platform:tenant')}${row('ООО ЧОО «Вектор»','vector',['Trial','48','2',pill('DEGRADED','warning')],'platform:tenant')}</tbody></table></div>`}
  function tenantDetail(){return `${pageHead('ООО ЧОП «Оберег»','Tenant obereg · ИНН 5836•••••• · создан 21.08.2026',`${btn('Break-glass','key')}${btn('Настройки','settings','primary')}`)}<div class="grid cols-4">${metric('Сотрудники','247','лимит 300','users')}${metric('Объекты','9','лимит 15','building')}${metric('Хранилище','18.4 GB','из 50 GB','server')}${metric('API ошибки','0.12%','24 часа','activity')}</div><div class="grid cols-2 section"><div class="card"><div class="card-head"><h3>Лимиты</h3></div><div class="list">${mini('users','Сотрудники','247 / 300','success')}${mini('building','Объекты','9 / 15','success')}${mini('file','Файлы','18.4 / 50 GB','success')}</div></div><div class="card"><div class="card-head"><h3>Сервисы</h3></div>${mini('server','API','Healthy · p95 184 ms','success')}${mini('server','Worker','Healthy · queue 4','success')}${mini('server','S3','Healthy','success')}${mini('alert','SMS adapter','2 transient errors','warning')}</div></div>`}
  function plansScreen(){return `${pageHead('Тарифы и лимиты','Конфигурация ограничений платформы и пилотных организаций.',btn('Создать тариф','plus','primary'))}<div class="grid cols-3"><div class="card"><div class="card-head"><h3>Trial</h3>${tag('30 дней')}</div><div style="font-size:28px;font-weight:800">50</div><p style="color:var(--muted)">сотрудников · 3 объекта · 5 GB</p>${btn('Настроить','settings')}</div><div class="card" style="border-color:#b9c7fa"><div class="card-head"><h3>Pilot</h3>${tag('Основной','primary')}</div><div style="font-size:28px;font-weight:800">300</div><p style="color:var(--muted)">сотрудников · 15 объектов · 50 GB</p>${btn('Настроить','settings','primary')}</div><div class="card"><div class="card-head"><h3>Commercial</h3>${tag('Roadmap')}</div><div style="font-size:28px;font-weight:800">∞</div><p style="color:var(--muted)">индивидуальные лимиты и SLA</p>${btn('Настроить','settings')}</div></div>`}
  function flagsScreen(){return `${pageHead('Feature flags','Управление включением рисковых или пилотных функций по tenant.',btn('Создать flag','plus','primary'))}<div class="card">${[['offline_sync_v2','Новая стратегия offline sync','on'],['incident_voice','Голосовые вложения в инцидентах','on'],['checkin_photo','Фото при check-in','off'],['client_ack','Подтверждение отчета заказчиком','on'],['maps_provider_beta','Новый картографический адаптер','off']].map(([k,d,on])=>`<div class="list-row"><div class="mini-icon">${ico('flag')}</div><div class="grow"><strong>${k}</strong><small>${d}</small></div><span class="tag">12 tenants</span><div class="toggle ${on==='on'?'on':''}" data-toggle></div></div>`).join('')}</div>`}
  function healthScreen(){return `${pageHead('Platform health','Состояние сервисов, очередей, интеграций и фоновых задач.')}<div class="grid cols-4">${metric('API','Healthy','p95 176 ms','server')}${metric('Queue','4','max age 8 sec','activity')}${metric('Errors','0.09%','−0.03 p.p.','alert')}${metric('Storage','Healthy','S3 RU','server')}</div><div class="grid cols-2 section"><div class="card"><div class="card-head"><h3>Сервисы</h3></div>${mini('server','API Gateway','Uptime 99.99%','success')}${mini('server','PHP Worker','4 jobs · max age 8 sec','success')}${mini('server','MySQL','Connections 32 / 150','success')}${mini('server','Redis','Memory 41%','success')}</div><div class="card"><div class="card-head"><h3>Интеграции</h3></div>${mini('phone','SMS / OTP','99.7% delivered','success')}${mini('bell','Mobile Push','99.9% accepted','success')}${mini('map','Maps','p95 310 ms','success')}${mini('alert','Email','2 delayed deliveries','warning')}</div></div>`}
  function versionsScreen(){return `${pageHead('Версии контента','Системные справочники, шаблоны, политики и публикации.',btn('Новая версия','plus','primary'))}<div class="table-wrap"><table class="data-table"><thead><tr><th>Контент</th><th>Версия</th><th>Статус</th><th>Опубликован</th><th>Автор</th></tr></thead><tbody>${row('Compliance rules','Справочник',['1.6',pill('PUBLISHED','success'),'25.09.2026','Platform Admin'],null)}${row('Шаблон отчета','Customer monthly',['2.1',pill('PUBLISHED','success'),'22.09.2026','Product'],null)}${row('Политика согласий','Mobile consents',['1.3',pill('DRAFT','warning'),'—','Legal'],null)}</tbody></table></div>`}
  function breakglass(){return `${pageHead('Break-glass audit','Временные привилегированные доступы поддержки с причиной и сроком.')}<div class="notice warning"><strong>Правило:</strong>&nbsp;каждый доступ требует причины, tenant, срока и фиксируется в отдельном журнале.</div><div class="table-wrap section"><table class="data-table"><thead><tr><th>Оператор</th><th>Tenant</th><th>Причина</th><th>Срок</th><th>Статус</th></tr></thead><tbody>${row('Support #12','platform-support',['ООО ЧОО «Вектор»','Разбор сбоя импорта','29.09 08:00–09:00',pill('EXPIRED','success')],null)}${row('SRE #03','platform-sre',['ООО ЧОП «Барьер»','Диагностика worker','29.09 09:00–09:30',pill('ACTIVE','warning')],null)}</tbody></table></div>`}
  function platformAudit(){return `${pageHead('Системный аудит','Платформенные действия без доступа к лишнему содержимому tenant.')}<div class="table-wrap"><table class="data-table"><thead><tr><th>Actor</th><th>Действие</th><th>Tenant</th><th>Время</th><th>Результат</th></tr></thead><tbody>${row('Platform Admin','operator@choppro',['tenant.updated','obereg','08:58:14',pill('OK','success')],null)}${row('SRE #03','sre@choppro',['break_glass.started','barrier','08:49:02',pill('OK','success')],null)}${row('System Worker','worker@choppro',['integration.retry','vector','08:31:55',pill('OK','success')],null)}</tbody></table></div>`}
  function renderPlatform(id){if(id==='login')return authScreen('platform','login');let c=id==='tenants'?platformTenants():id==='tenant'?tenantDetail():id==='plans'?plansScreen():id==='flags'?flagsScreen():id==='health'?healthScreen():id==='versions'?versionsScreen():id==='breakglass'?breakglass():platformAudit();return shell('platform',id,c)}
